// Per-tab toolbar verdict — whether the tab is a downloadable animepahe page —
// shown both on the action icon (✓/✗ corner disc) and as a badge, so it's legible
// without opening the popup. Derived state only: nothing here is persisted, and
// the queue is untouched.
import { loadSettings } from '@/lib/settings';
import { matchTab } from '@/lib/match';

/** Icon variants generated by scripts/gen-icons.mjs; paths are dist-root relative. */
const iconPaths = (variant: '' | '-ok' | '-bad') => ({
  16: `icons/icon${variant}-16.png`,
  32: `icons/icon${variant}-32.png`,
  48: `icons/icon${variant}-48.png`,
  128: `icons/icon${variant}-128.png`,
});

const OK = { icon: iconPaths('-ok'), text: '✓', color: '#2ea043' };
const BAD = { icon: iconPaths('-bad'), text: '✗', color: '#d1242f' };
const NEUTRAL = { icon: iconPaths(''), text: '', color: '' };

/**
 * Paint icon + badge for one tab. Unrelated sites get the plain brand mark and no
 * badge: a red cross on every tab in the browser would be noise, so the cross is
 * reserved for animepahe hosts sitting on the wrong page (home, /play/, search).
 */
export async function updateBadge(tabId: number, url?: string): Promise<void> {
  const { animepaheDomain } = await loadSettings();
  const m = matchTab(url, animepaheDomain);
  const verdict = m.ok ? OK : m.onAnimepahe ? BAD : NEUTRAL;

  try {
    await chrome.action.setIcon({ tabId, path: verdict.icon });
    await chrome.action.setBadgeText({ tabId, text: verdict.text });
    if (verdict.color) {
      await chrome.action.setBadgeBackgroundColor({ tabId, color: verdict.color });
      await chrome.action.setBadgeTextColor({ tabId, color: '#ffffff' });
    }
  } catch {
    // Tab closed between the event firing and the call ("No tab with id") — ignore.
  }
}

/** Repaint every open tab, for SW startup/install where no navigation will fire. */
export async function refreshAllBadges(): Promise<void> {
  const tabs = await chrome.tabs.query({});
  await Promise.all(tabs.map((t) => (t.id == null ? undefined : updateBadge(t.id, t.url))));
}
